# recursively find fields with options containing hg38 or human/homo/grch
def walk(o,path=''):
    if isinstance(o,dict):
        name=o.get('name') or o.get('label') or ''
        opts=o.get('options') or o.get('select_options') or []
        if isinstance(opts,list):
            for opt in opts:
                label=(opt.get('label') if isinstance(opt,dict) else str(opt)).lower()
                val=(opt.get('value') if isinstance(opt,dict) else opt)
                if any(s in label or s in str(val).lower() for s in ['hg38','grch38','homo sapiens','human','hg19','grch37']):
                    print('MATCH path',path,'name',name,'label',o.get('label'),'value',val,'label',opt.get('label') if isinstance(opt,dict) else opt)
        for k,v in o.items():
            walk(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f'[{i}]')
walk(data)
